public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || row < 0 || row >= table.getRowCount()) {
        return;
    }
    table.getRowSelectionInterval().deleteAll();
    table.addRowSelectionInterval(row, row);
    if (pane != null) {
        int y = table.getY() + table.getRowHeight(row);
        int x = table.getX();
        int width = table.getWidth();
        int height = table.getRowHeight(row);
        pane.getViewport().scrollRectToVisible(new Rectangle(x, y - height, width, height));
        repaintLater();
    } else {
        table.scrollRectToVisible(new Rectangle(0, table.getY() + table.getRowHeight(row), table.getWidth(), table.getRowHeight(row)));
    }
}

